import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  itemActionsClassName,
  itemClassName,
  itemContentClassName,
  itemDescriptionClassName,
  itemFooterClassName,
  itemGroupClassName,
  itemHeaderClassName,
  itemMediaClassName,
  itemMediaVariantClassNames,
  itemSeparatorClassName,
  itemSizeClassNames,
  itemTitleClassName,
  itemVariantClassNames,
} from "./view";

export {
  itemActionsClassName,
  itemButtonClassName,
  itemClassName,
  itemContentClassName,
  itemDescriptionClassName,
  itemFooterClassName,
  itemGroupClassName,
  itemHeaderClassName,
  itemMediaClassName,
  itemMediaVariantClassNames,
  itemSeparatorClassName,
  itemSizeClassNames,
  itemTitleClassName,
  itemVariantClassNames,
} from "./view";

export type ItemVariant = "default" | "outline" | "muted";
export type ItemSize = "default" | "sm" | "xs";
export type ItemMediaVariant = "default" | "icon" | "avatar" | "image";

export type ItemViewConfig = Readonly<{
  children: readonly (Html | string)[];
  variant?: ItemVariant;
  size?: ItemSize;
  className?: string;
  href?: string;
}>;
export type ItemPartViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;
export type ItemMediaViewConfig = ItemPartViewConfig &
  Readonly<{ variant?: ItemMediaVariant }>;

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>({
  children,
  variant = "default",
  size = "default",
  className,
  href,
}: ItemViewConfig): Html => {
  const h = html<ParentMessage>();
  const attributes = [
    h.DataAttribute("slot", "item"),
    h.Class(
      classNames(
        itemClassName,
        itemVariantClassNames[variant],
        itemSizeClassNames[size],
        className
      )
    ),
  ];
  if (href !== undefined) {
    return h.a([h.Href(href), ...attributes], children);
  }
  return h.div(attributes, children);
};

export const groupView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-group"),
      h.Class(classNames(itemGroupClassName, className)),
    ],
    children
  );
};

export const separatorView = <ParentMessage>(): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [h.Attribute("role", "separator"), h.Class(itemSeparatorClassName)],
    []
  );
};

export const headerView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-header"),
      h.Class(classNames(itemHeaderClassName, className)),
    ],
    children
  );
};

export const mediaView = <ParentMessage>({
  children,
  variant = "default",
  className,
}: ItemMediaViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-media"),
      h.Class(
        classNames(
          itemMediaClassName,
          itemMediaVariantClassNames[variant],
          className
        )
      ),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-content"),
      h.Class(classNames(itemContentClassName, className)),
    ],
    children
  );
};

export const titleView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.h3(
    [
      h.DataAttribute("slot", "item-title"),
      h.Class(classNames(itemTitleClassName, className)),
    ],
    children
  );
};

export const descriptionView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.p(
    [
      h.DataAttribute("slot", "item-description"),
      h.Class(classNames(itemDescriptionClassName, className)),
    ],
    children
  );
};

export const actionsView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-actions"),
      h.Class(classNames(itemActionsClassName, className)),
    ],
    children
  );
};

export const footerView = <ParentMessage>({
  children,
  className,
}: ItemPartViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [
      h.DataAttribute("slot", "item-footer"),
      h.Class(classNames(itemFooterClassName, className)),
    ],
    children
  );
};

export const itemClassName =
  "group/item flex w-full items-start gap-4 rounded-lg p-4 text-left transition-colors";
export const itemVariantClassNames = {
  default: "bg-transparent",
  outline: "border border-gray-200 bg-white shadow-sm",
  muted: "bg-gray-100/80",
} as const;
export const itemSizeClassNames = {
  default: "min-h-20",
  sm: "min-h-16 p-3",
  xs: "min-h-12 gap-3 p-2.5 text-sm",
} as const;
export const itemGroupClassName =
  "grid overflow-hidden rounded-lg border border-gray-200 bg-white";
export const itemSeparatorClassName = "h-px bg-gray-200";
export const itemHeaderClassName = "mb-2 text-sm font-medium text-gray-500";
export const itemMediaClassName =
  "flex shrink-0 items-center justify-center overflow-hidden rounded-md";
export const itemMediaVariantClassNames = {
  default: "size-10 bg-gray-100 text-gray-700",
  icon: "size-10 border border-gray-200 bg-white text-gray-700",
  avatar: "size-10 rounded-full bg-accent-100 font-medium text-accent-700",
  image: "size-14 rounded-md bg-gray-100 object-cover",
} as const;
export const itemContentClassName = "min-w-0 flex-1 space-y-1";
export const itemTitleClassName = "font-medium leading-none text-gray-950";
export const itemDescriptionClassName = "text-sm leading-5 text-gray-600";
export const itemActionsClassName = "ml-auto flex shrink-0 items-center gap-2";
export const itemFooterClassName = "mt-3 text-xs text-gray-500";
export const itemButtonClassName =
  "inline-flex h-9 items-center rounded-md border border-gray-300 bg-white px-3 text-sm font-medium text-gray-950 shadow-sm transition hover:bg-gray-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Item from "./index";

describe("Item registry view", () => {
  test("renders item anatomy", () => {
    const view = (): Html =>
      Item.view<never>({
        variant: "outline",
        children: [
          Item.mediaView<never>({ variant: "icon", children: ["✓"] }),
          Item.contentView<never>({
            children: [
              Item.titleView<never>({ children: ["Verified"] }),
              Item.descriptionView<never>({
                children: ["Your profile has been verified."],
              }),
            ],
          }),
        ],
      });

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Verified")).toExist(),
      Scene.expect(Scene.text("Your profile has been verified.")).toExist()
    );
  });
});
